WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY carrier ORDER BY cost NULLS LAST, id) AS rank_in_group FROM shipments) t WHERE rank_in_group = 1) SELECT status, DATE_TRUNC('WEEK', shipped_date) AS week_start, CASE WHEN cost >= 104 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN carrier = 'DHL' THEN 1 END), 0), 2) AS cost_per_dhl, COUNT(*) FILTER (WHERE status = 'RETURNED') AS returned_rows, STDDEV_SAMP(cost) AS cost_stddev, STDDEV_SAMP(cost) AS cost_stddev_2 FROM latest GROUP BY status, week_start, cost_tier;
